def second_smallest(nums):
    if not nums:
        raise ValueError("List is empty")
    sorted_nums = sorted(nums)
    if len(sorted_nums) == 1:
        return sorted_nums[0]
    # Since duplicates are allowed, second smallest can be same as smallest
    return sorted_nums[1]

import re

def remove_multiple_spaces(s: str) -> str:
    return re.sub(r'\s+', ' ', s).strip()

def is_Two_Alter(s: str) -> bool:
    # Check if the string has exactly two unique characters
    unique_chars = set(s)
    if len(unique_chars) != 2:
        return False

    # Check if the characters strictly alternate
    for i in range(len(s) - 1):
        if s[i] == s[i+1]:
            return False

    return True

def max_sub_array_sum(arr):
    if not arr:
        return 0

    max_sum = current_sum = arr[0]

    for num in arr[1:]:
        current_sum = max(num, current_sum + num)
        max_sum = max(max_sum, current_sum)

    return max_sum

def len_log(words):
    if not words:
        return 0
    return max(len(word) for word in words)

def count_nums(arr):
    def sum_signed_digits(n):
        s = str(n)
        total = 0
        for i, ch in enumerate(s):
            if ch == '-':
                continue
            digit = int(ch)
            if i == 0 and s[0] == '-':
                # first digit after '-' is negative
                digit = -digit
            total += digit
        return total

    count = 0
    for num in arr:
        if sum_signed_digits(num) > 0:
            count += 1
    return count

def minPath(grid, k):
    from collections import deque

    N = len(grid)
    # Directions for neighbors (up, down, left, right)
    directions = [(-1,0),(1,0),(0,-1),(0,1)]

    # We want the lex smallest path of length k.
    # Since revisits are allowed, we can use BFS with pruning.
    #
    # A key insight:
    # - At each step, from all states, keep only the lex smallest paths leading to each cell.
    # - Because lex order depends on the whole path, store full paths.
    # - But k can be large; to keep it efficient:
    #    - At each step, for each cell, keep only the lex smallest path reaching it.
    #
    # This way, after k steps, we have for each cell the lex smallest path of length k ending there.
    # Finally, among all these, choose the lex smallest path overall.

    # Initialize dp: for step 1, paths of length 1 starting at each cell
    dp = [[None]*N for _ in range(N)]
    for r in range(N):
        for c in range(N):
            dp[r][c] = [grid[r][c]]

    for step in range(2, k+1):
        new_dp = [[None]*N for _ in range(N)]
        for r in range(N):
            for c in range(N):
                # Current path at dp[r][c] is the lex smallest path of length step-1 ending at (r,c)
                if dp[r][c] is None:
                    continue
                cur_path = dp[r][c]
                for dr, dc in directions:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < N and 0 <= nc < N:
                        new_path = cur_path + [grid[nr][nc]]
                        old_path = new_dp[nr][nc]
                        # Update only if no path stored yet or new_path is lex smaller
                        if old_path is None or new_path < old_path:
                            new_dp[nr][nc] = new_path
        dp = new_dp

    # Among all dp[r][c], pick the lex smallest path of length k
    answer = None
    for r in range(N):
        for c in range(N):
            if dp[r][c] is not None:
                if answer is None or dp[r][c] < answer:
                    answer = dp[r][c]

    return answer

def words_in_sentence(sentence):
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    words = sentence.split()
    prime_length_words = [word for word in words if is_prime(len(word))]
    return " ".join(prime_length_words)

